'use strict';
const WorksiteRoutes=(()=>{
const sites={
a:{name:'Nordhang',boundary:[[7,10],[87,8],[94,78],[80,88],[15,86],[6,62]],hazard:{x:18,z:35,r:9,label:'BIO-01 · Habitatbaum'},harvester:[[30,16],[30,74],[48,74],[48,16],[66,16],[66,74],[82,74],[82,16]],forwarder:[[52,96],[52,84],[30,78],[30,16],[48,16],[48,74],[66,74],[66,16],[82,16],[82,78],[52,84],[52,96]],polter:[52,96]},
b:{name:'Talgrund',boundary:[[8,10],[87,9],[94,72],[83,86],[16,86],[6,56]],hazard:{x:84,z:40,r:12,label:'BIO-02 · Feuchtbiotop'},harvester:[[25,16],[25,74],[43,74],[43,16],[61,16],[61,74]],forwarder:[[52,96],[52,84],[25,78],[25,16],[43,16],[43,74],[61,74],[61,16],[61,78],[52,84],[52,96]],polter:[52,96]},
c:{name:'Südrevier',boundary:[[8,12],[88,12],[94,74],[79,86],[16,86],[6,56]],hazard:{x:55,z:20,r:13,label:'BIO-03 · Horstverdacht'},harvester:[[25,42],[25,74],[43,74],[43,42],[61,42],[61,74],[79,74],[79,42]],forwarder:[[52,96],[52,84],[25,78],[25,42],[43,42],[43,74],[61,74],[61,42],[79,42],[79,78],[52,84],[52,96]],polter:[52,96]}
};
sites.a.anchor=[40,55,1.65];sites.b.anchor=[290,20,1.45];sites.c.anchor=[290,185,1.4];
const imageUrl='assets/forest-orthophoto.jpg';
function attribution(){return `<p class="map-attribution">Luftbild: <a href="https://www.bezreg-koeln.nrw.de/geobasis-nrw/produkte-und-dienste/luftbild-und-satellitenbildinformationen/aktuelle-luftbild-und-0" target="_blank" rel="noopener">Geobasis NRW / Land NRW</a> · <a href="https://www.govdata.de/dl-de/zero-2-0" target="_blank" rel="noopener">dl-de/zero-2-0</a> · Abruf 30.09.2026 · kein Livebild. Teutoburger Wald. Grenzen, Wege, Baumarten und Funde sind fiktive Spielauflagen; keine amtliche Flurkarte.</p>`;}
function imageLayer(id){const [x,y,k]=sites[id].anchor;return `<image class="aerial-layer" href="${imageUrl}" x="${-x/k}" y="${-y/k}" width="${620/k}" height="${350/k}" preserveAspectRatio="none"/><rect x="-8" y="-7" width="116" height="121" fill="#002a44" fill-opacity=".18"/>`;}
function neighbour(id){return id==='a'?`<path d="M87,8 L108,8 L108,88 L80,88 L94,78 Z" fill="#ffb8a0" fill-opacity=".16" stroke="#ffb8a0" stroke-width=".65"/><path d="M87,8 L94,78 L80,88" fill="none" stroke="#fff" stroke-width="1.2"/><path d="M103,10 L103,78" stroke="#ff906f" stroke-width="1" stroke-dasharray="2 1"/><g fill="#ffdfd6" font-size="3.1" text-anchor="middle" style="paint-order:stroke;stroke:#173a42;stroke-width:1"><text x="98" y="24">Nachbar</text><text x="98" y="29">kein Auftrag</text><text x="99" y="69">Altskizze</text></g>`:'';}
function elevation(id,x,z){if(id==='a')return 3+12*(1-z/100)+2.5*Math.sin(x/22)*Math.cos(z/21);if(id==='b')return 3+5*((x-50)/50)**2+1.5*Math.sin(z/20);return 3+6*(1-x/100)+2*Math.sin(z/24);}
function length(path){return path.slice(1).reduce((a,p,i)=>a+Math.hypot(p[0]-path[i][0],p[1]-path[i][1]),0);}
function at(path,t){const total=length(path),target=Math.max(0,Math.min(1,t))*total;let distance=0;for(let i=1;i<path.length;i++){const a=path[i-1],b=path[i],d=Math.hypot(b[0]-a[0],b[1]-a[1]);if(distance+d>=target){const f=d?(target-distance)/d:0;return[a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f];}distance+=d;}return path.at(-1);}
function pathD(path){return path.map((p,i)=>(i?'L':'M')+p[0]+','+p[1]).join(' ');}
function mapSvg(id){const s=sites[id],h=s.hazard;let contour='';for(let z=10;z<95;z+=14){let points=[];for(let x=0;x<=100;x+=5)points.push([x,z+2*Math.sin(x/18+z/22)]);contour+=`<path d="${pathD(points)}"/>`;}return `<svg class="worksite-map-svg" viewBox="-8 -7 116 121" role="img" aria-label="Arbeitskarte ${s.name}: geplante Harvesterroute, Forwarderroute, Polter und Biodiversitätsschutzbereich"><defs><pattern id="site-hatch-${id}" width="4" height="4" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><line x1="0" y1="0" x2="0" y2="4" stroke="#f4a797" stroke-width="1"/></pattern></defs><rect x="-8" y="-7" width="116" height="121" fill="#073b62"/>${imageLayer(id)}<path d="${pathD(s.boundary)} Z" fill="#12567b" fill-opacity=".14" stroke="#b9d9ec" stroke-width=".65" stroke-dasharray="2 1.4"/>${neighbour(id)}<path d="M-8,96 H108" stroke="#aec9dd" stroke-width="4"/><path d="M-8,96 H108" stroke="#436784" stroke-width=".4" stroke-dasharray="2 3"/><circle cx="${h.x}" cy="${h.z}" r="${h.r}" fill="url(#site-hatch-${id})" stroke="#f4a797" stroke-width=".7"/><text x="${h.x}" y="${h.z+1.5}" text-anchor="middle" fill="#ffe4df" font-size="4" font-weight="700">${id==='a'?'BIO-01':id==='b'?'BIO-02':'BIO-03'}</text><path d="${pathD(s.forwarder)}" fill="none" stroke="#ffdf72" stroke-width="1.3" stroke-dasharray="2 1.4"/><path d="${pathD(s.harvester)}" fill="none" stroke="#52d5ff" stroke-width=".85"/><rect x="${s.polter[0]-3}" y="${s.polter[1]-3}" width="6" height="6" rx="1" fill="#eef7ff"/><text x="${s.polter[0]+5}" y="${s.polter[1]+1.5}" fill="#eef7ff" font-size="3.8">P-${id.toUpperCase()}01</text><rect x="${s.harvester[0][0]-3}" y="${s.harvester[0][1]-3}" width="6" height="6" rx="1" fill="#52d5ff"/><text x="${s.harvester[0][0]}" y="${s.harvester[0][1]+1.5}" text-anchor="middle" fill="#003f6b" font-size="4" font-weight="700">H</text><rect x="${s.polter[0]-3}" y="${s.polter[1]-3}" width="6" height="6" rx="1" fill="#ffdf72"/><text x="${s.polter[0]}" y="${s.polter[1]+1.5}" text-anchor="middle" fill="#003f6b" font-size="4" font-weight="700">F</text><text x="98" y="3" text-anchor="middle" fill="#d9ebf8" font-size="4">N</text><path d="M98,6 V13 M96,8 L98,6 L100,8" fill="none" stroke="#d9ebf8" stroke-width=".5"/><path d="M0,107 H31.25 M0,105 V109 M31.25,105 V109" fill="none" stroke="#b9d9ec" stroke-width=".6"/><text x="0" y="113" fill="#e3f1fa" font-size="3.5">ca. ${Math.round(31.25*sites[id].anchor[2]*1.331)} m · Planungsauflage</text></svg>`;}
function panel(id){const s=sites[id];return `<section class="report-section report-spatial"><div class="spatial-title"><h3>Arbeitskarte und geplante Maschinenwege</h3><span>H-${id.toUpperCase()}01</span></div><div class="spatial-tabs" role="group" aria-label="Kartenansicht"><button id="viewMap" aria-pressed="true">Arbeitskarte</button><button id="view3d" aria-pressed="false">3D-Überflug starten</button></div><div class="spatial-stage"><div id="routeMap">${mapSvg(id)}</div><div id="routeFly" hidden><canvas id="flyCanvas" aria-label="3D-Ansicht der geplanten Maschinenwege im ${s.name}"></canvas><div class="fly-overlay"><span>3D · ${s.name}</span><span id="flightStatus" aria-live="polite">Bereit</span></div><div id="flyUnavailable" hidden>Die 3D-Ansicht ist hier nicht verfügbar. Die vollständige Arbeitskarte zeigt dieselben geplanten Wege.</div></div></div><div class="map-layer-controls"><button id="aerialToggle" aria-pressed="true">Luftbild: an</button><label>Kartenzoom <input id="mapZoom" type="range" min="1" max="2.5" value="1" step=".1" aria-label="Kartenzoom"></label><span>Weiß: Auftrag · Orange: ungeprüfte Altskizze</span></div><div class="route-legend"><span><i class="h-line"></i>Harvester H-01 · ${Math.round(length(s.harvester)*sites[id].anchor[2]*1.331)} m</span><span><i class="f-line"></i>Forwarder F-01 · ${Math.round(length(s.forwarder)*sites[id].anchor[2]*1.331)} m</span><span><i class="bio-area"></i>Schutzbereich · aussparen</span></div><div class="fly-controls" id="flyControls" hidden><button id="flightPlay">Pause</button><button id="flightReset">Neu starten</button><button id="flightRotate">Ansicht drehen</button><label>Überflug <input id="flightProgress" type="range" min="0" max="100" value="0" aria-label="Fortschritt des 3D-Überflugs"></label></div><p class="report-note">Geplante Routen als H/F-Marker. Die 2D-Karte nutzt ein reales Luftbild; Grenzen und Schutzflächen sind erfunden. 3D-Höhen sind modelliert, keine Geländevermessung. Kein live erfasster Maschinenstand und keine automatisch geprüfte Rückegassenplanung.</p>${attribution()}</section>`;}
return{sites,imageUrl,attribution,imageLayer,neighbour,elevation,length,at,pathD,mapSvg,panel};})();
if(typeof module!=='undefined')module.exports=WorksiteRoutes;
